const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.query) {
  errors.push('Missing required parameter: query');
}
if (!body.entity_type) {
  errors.push('Missing required parameter: entity_type');
}
if (!body.qdrant_host) {
  errors.push('Missing required parameter: qdrant_host');
}
if (!body.qdrant_port) {
  errors.push('Missing required parameter: qdrant_port');
}
if (!body.qdrant_collection) {
  errors.push('Missing required parameter: qdrant_collection');
}
if (!body.openai_api_key) {
  errors.push('Missing required parameter: openai_api_key');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const qdrantUrl = `http://${body.qdrant_host}:${body.qdrant_port}`;

return [{
  json: {
    valid: true,
    query: body.query,
    entity_type: body.entity_type,
    limit: body.limit || 10,
    filters: body.filters || {},
    user_id: body.user_id,
    qdrant_url: qdrantUrl,
    qdrant_collection: body.qdrant_collection,
    openai_api_key: body.openai_api_key
  }
}];

const input = $input.first().json;
 const prevData = $('Validate Input').first().json;

 try {
   if (input.error || input.status?.error) {
     return [{
       json: {
         success: false,
         error: {
           code: 500,
           message: input.error?.message || input.status?.error || 'Qdrant search failed',
           status: 'SEARCH_ERROR'
         },
         meta: { provider: 'qdrant', collection: prevData.qdrant_collection }
       }
     }];
   }

   const results = (input.result || []).map(item => ({
     id: item.id,
     score: item.score,
     entity: item.payload || {}
   }));

   // Apply filters if any
   let filtered = results;
   const filters = prevData.filters;

   if (filters.max_time_minutes) {
     filtered = filtered.filter(r => {
       const total = (r.entity.prep_time_minutes || 0) + (r.entity.cook_time_minutes || 0);
       return total <= filters.max_time_minutes;
     });
   }

   if (filters.vegetarian) {
     filtered = filtered.filter(r => r.entity.tags?.includes('vegetarian') || r.entity.tags?.includes('végétarien'));
   }

   if (filters.vegan) {
     filtered = filtered.filter(r => r.entity.tags?.includes('vegan') || r.entity.tags?.includes('végan'));
   }

   return [{
     json: {
       success: true,
       data: {
         results: filtered,
         total: filtered.length,
         query: prevData.query,
         entity_type: prevData.entity_type
       },
       meta: {
         provider: 'qdrant',
         collection: prevData.qdrant_collection,
         query_embedding_used: true,
         original_count: results.length,
         filtered_count: filtered.length
       }
     }
   }];
 } catch (e) {
   return [{
     json: {
       success: false,
       error: {
         code: 500,
         message: 'Failed to process search results: ' + e.message,
         status: 'PROCESS_ERROR'
       },
       meta: { provider: 'qdrant' }
     }
   }];
 }

